function meRowFromCareer(x, cl, selfKey, selfName, idx){
  const qual = !!x.qualifying || /^qualif/i.test(String(x.round || ''));
  const r = {
    mid: fhSafeId('me' + selfKey + '_' + idx + '_' + (x.eventKey != null ? x.eventKey : x.date)),
    date: x.date, tourn: (typeof sfEventName === 'function' ? sfEventName : fhTournClean)(x.tournament), tournRaw: x.tournament,   // TEN-402 r1 fix 2: the one event name
    surface: fhSurfName(x.surface), round: fhRoundCode(x.round, qual),
    opp: x.opponent, oppKey: null, won: !!x.won, result: x.result,
    sets: fhSetsFrom(x.sets), ret: !!x.retired, wo: !!x.walkover, def: !!x.defaulted, qualifying: qual, tier: x.level === 'atp' ? 'atp' : x.level,
    ek: x.eventKey != null ? x.eventKey : null, selfKey, selfName, price: null, oppPrice: null, book: null, src: null,
    level: fhLevelOf(x.level, x.tournament, null),
    alt: x.altFormat ? String(x.altFormat) : (ME_NONSTD_EVENT.test(String(x.tournament || '')) ? 'team event' : null),
  };
  fhFinishRow(r);
  // The history's own best-of, where it records one, beats the Slam-name inference.
  if ((x.bestOf === 3 || x.bestOf === 5) && x.bestOf !== r.bo){
    r.bo = x.bestOf;
    // Re-read the retirement under the history's format, both ways: a 2–0 win the Slam-name guess (Bo5) flagged
    // as stopped short is complete in a best-of-3 (TEN-336); a Bo5 winner short of three sets stopped.
    const unfinished = !!(r.sets && r.done && r.done.length < r.sets.length);
    r.ret = !r.wo && (!!x.retired || unfinished || (r.pS != null && (r.won ? r.pS : r.oS) < (r.bo === 5 ? 3 : 2)));
    r.complete = !r.ret && !r.wo && r.pS != null;
    r.decider = r.complete && r.pS != null && (r.pS + r.oS) === r.bo;   // fhFinishRow's rule, under the recorded format
  }
  if (!r.wo && cl){
    const d0 = fhDayNum(r.date), nk = fhNameKey(r.opp), hi = d0 + (x.src === 'archive' ? 14 : 1);
    const inWin = y => { const d = fhDayNum(y.date); return d != null && d >= d0 - 1 && d <= hi && y.won === r.won; };
    let hits = d0 == null || !nk ? [] : (cl.rows || []).filter(y => inWin(y) && fhNameKey(y.opp) === nk);
    // One surname a prefix of the other ("A. Ramos" / "Ramos-Vinolas A.", "G. Mpetshi Perricard" / "Mpetshi G."):
    // accepted only when exactly one row in the window qualifies, with the same result.
    if (!hits.length && d0 != null && nk.length >= 4) hits = (cl.rows || []).filter(y => { const k2 = fhNameKey(y.opp); return inWin(y) && k2.length >= 4 && k2 !== nk && (k2.startsWith(nk) || nk.startsWith(k2)); });
    // founder ruling 2026-10-18: an opponent the archive spells another way and who carries no key ("Del Potro J.M." =
    // "J. Martin del Potro") meets his row through the ONE name table the price join reads (ARCHIVE_PAGE_SPELLINGS, published
    // as database-yield-players.json `aliases`); still exactly one row in the window, same result
    const AL = !hits.length && d0 != null && typeof _sfDbJoin !== 'undefined' && _sfDbJoin && _sfDbJoin.aliases;
    if (AL) hits = (cl.rows || []).filter(y => inWin(y) && Object.prototype.hasOwnProperty.call(AL, y.opp) && [].concat(AL[y.opp]).some(v => fhNameKey(v) === nk));
    const td = hits.length === 1 ? hits[0] : null;
    if (td) r.tdKey = td.date + '|' + td.opp + '|' + (td.won ? 1 : 0);   // the Tennis-Data row it joined (ruling B join)
    if (td && x.src === 'archive') r.date = td.date;
    const c = fhCloseFor(cl, td ? td.date : r.date, td ? td.opp : r.opp, r.won, td ? td.oppKey : null, r.ek);
    if (c){ r.price = c.price; r.oppPrice = c.oppPrice; r.book = c.book; r.src = c.src; r.srcLabel = c.srcLabel; }
    if (td && td.oppKey) r.oppKey = td.oppKey;
    if (td && td.ret) r.retSettle = true;
  }
  // Settlement: a retirement is what the feed flags or what Tennis-Data (the price's own archive)
  // marks as not "Completed". Ruling A (2026-09-28): it settles the match-winner bet at the close, but
  // never enters the Derived lines (its unfinished set is not a completed set; `whyNotBo3`). A completed
  // match whose stored set list is shorter than its result ("3 - 0" with two sets) is NOT a
  // retirement: its result stands; only the set-score lines cannot read it (`setsOk`).
  r.retSettle = !!(r.retSettle || x.retired);
  // founder ruling 2026-10-17 (item 1): the Database's own price wherever its join holds this match (sfDbPxRows) — the
  // career row as the Head to Head page and the profile hand it over (its own date, result, round and opponent)
  // ruling 3: an ATP tour-level row (the master's class) reads the join only — a dash where it holds none, has not loaded
  // or failed. (sfDbPxRows is always defined on the page; only a data-layer harness slices this function without it.)
  if (!r.wo && !qual && r.level === 'ATP' && typeof sfDbPxRows === 'function'){
    const d = sfDbPxRows(selfKey, selfName, [{ date: x.date, won: r.won, round: r.round, opp: x.opponent }])[0];
    if (d){ r.price = d.price; r.oppPrice = d.oppPrice; r.book = d.book; r.src = d.src; r.srcLabel = d.srcLabel; }
    else { r.price = null; r.oppPrice = null; r.book = null; r.src = null; r.srcLabel = null; }
  }
  const res = /^\s*(\d+)\s*-\s*(\d+)\s*$/.exec(String(x.result || ''));
  r.setsOk = !!(r.sets && res && r.sets.length === (+res[1]) + (+res[2]) && r.done && r.done.length === r.sets.length);
  r.day = fhDayNum(r.date);
  return r;
}
// A player's normalised rows, ATP tour level only (the price archive is ATP main draw; the
// other levels are counted out loud, never silently dropped): `rows.notTour` = the count left out.
